def verify():
    assert abs(7.85 / 2.7 - 2.907) < 0.001 and abs(1 - math.exp(-0.25 * 2.1 ** 2) - 0.668) < 0.001
    assert abs(2 * math.sqrt(2) * 0.128 - 0.362) < 0.001 and abs(4 * 63.5 / ((0.3615e-7) ** 3 * NA_) - 8.93) < 0.02
    assert abs(math.degrees(math.asin(0.385)) - 22.64) < 0.01 and abs(0.4 / math.sqrt(2) - 0.2828) < 0.0001
    assert abs(math.exp(-0.9 / (KB * 1000)) * 1e5 - 2.9) < 0.05 and abs(math.sqrt(1e-7) * 1000 - 0.316) < 0.001
    assert 70 + 0.74 / math.sqrt(1e-4) == 144 and abs(200 * math.sqrt(math.pi * 0.002) - 15.85) < 0.01
    assert abs((50 / 250) ** 2 / math.pi * 1000 - 12.73) < 0.01 and abs(3.5 / 11 - 0.318) < 0.001
    assert abs(0.36 / 0.738 - 0.488) < 0.001 and abs(1 / 5.8e7 * 1e8 - 1.724) < 0.001


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
